"""出征准备页面基类 — 声明共享依赖与公共查询 / 导航方法。

所有准备页 Mixin 均继承 :class:`BaseBattlePreparation`，
最终由 :class:`~autowsgr.ui.battle.preparation.BattlePreparationPage` 组合。
"""

from __future__ import annotations

import enum
from typing import TYPE_CHECKING

from autowsgr.image_resources import Templates
from autowsgr.infra.logger import get_logger
from autowsgr.types import PageName
from autowsgr.ui.battle.constants import (
    AUTO_SUPPLY_ON,
    AUTO_SUPPLY_PROBE,
    CLICK_AUTO_SUPPLY,
    CLICK_BACK,
    CLICK_FLEET,
    CLICK_SHIP_SLOT,
    CLICK_START_BATTLE,
    FLEET_ACTIVE,
    FLEET_PROBE,
    PANEL_ACTIVE,
    STATE_TOLERANCE,
)
from autowsgr.ui.stack import record_page_substate
from autowsgr.ui.substate import SubstateSpec
from autowsgr.ui.utils import NavConfig, NavigationError, click_and_wait_for_page
from autowsgr.vision import ImageChecker, PageMatch, PixelChecker
from autowsgr.vision.thresholds import TEMPLATE_PAGE


if TYPE_CHECKING:
    import numpy as np

    from autowsgr.context import GameContext
    from autowsgr.vision import OCREngine

_log = get_logger('ui.preparation')


# ═══════════════════════════════════════════════════════════════════════════════
# 枚举
# ═══════════════════════════════════════════════════════════════════════════════


class RepairStrategy(enum.Enum):
    """修理策略。"""

    MODERATE = 'moderate'
    """修中破及以上 (damage >= 1)。"""

    SEVERE = 'severe'
    """仅修大破 (damage >= 2)。"""

    ALWAYS = 'always'
    """有损伤即修 (damage >= 1, 含黄血)。"""

    NEVER = 'never'
    """不修理。"""


class Panel(enum.Enum):
    """出征准备底部面板标签。"""

    STATS = '综合战力'
    QUICK_SUPPLY = '快速补给'
    QUICK_REPAIR = '快速修理'
    EQUIPMENT = '装备预览'


PANEL_PROBE: dict[Panel, tuple[float, float]] = {
    Panel.STATS: (0.1214, 0.7907),
    Panel.QUICK_SUPPLY: (0.2625, 0.7944),
    Panel.QUICK_REPAIR: (0.3932, 0.7926),
    Panel.EQUIPMENT: (0.5250, 0.7926),
}
"""面板标签探测点。选中项探测颜色 ≈ (30, 139, 240)。"""

CLICK_PANEL: dict[Panel, tuple[float, float]] = {
    Panel.STATS: (0.155, 0.793),
    Panel.QUICK_SUPPLY: (0.286, 0.793),
    Panel.QUICK_REPAIR: (0.417, 0.793),
    Panel.EQUIPMENT: (0.548, 0.793),
}
"""面板标签点击位置。"""


# ═══════════════════════════════════════════════════════════════════════════════
# 基类
# ═══════════════════════════════════════════════════════════════════════════════


class BaseBattlePreparation:
    """出征准备页面基类。

    声明所有 Mixin 需要的共享依赖与公共查询 / 导航方法。

    Parameters
    ----------
    ctx:
        游戏上下文。
    ocr:
        OCR 引擎实例 (可选)。
    """

    def __init__(self, ctx: GameContext, ocr: OCREngine | None = None) -> None:
        self._ctx = ctx
        self._ctrl = ctx.ctrl
        self._ocr = ocr or ctx.ocr
        self._ship_ocr = getattr(ctx, 'ship_ocr', None)

    @property
    def _preferred_ocr(self) -> OCREngine | None:
        """返回船只识别优先使用的 OCR 引擎。

        增强船只识别 (FastOCR) 开启时优先使用它，未开启时回退默认 OCR。
        只有名称 / 等级 / 舰种等船只信息节点应使用本属性，其余节点仍用 ``_ocr``。
        """
        return self._ship_ocr or self._ocr

    # ── 页面识别 ──────────────────────────────────────────────────────────

    @staticmethod
    def is_current_page(screen: np.ndarray) -> PageMatch:
        """判断截图是否为出征准备页面。

        用出征准备页面独有特征模板匹配 (迁移自 classic ``fight_prepare_page``,
        183x48 局部特征), 返回带置信度的 :class:`PageMatch` 供候选集排序。
        """
        detail = ImageChecker.find_best(
            screen, [Templates.Page.BATTLE_PREP], confidence=0.0
        )
        score = detail.confidence if detail is not None else 0.0
        name = PageName.BATTLE_PREP.value
        return PageMatch(
            name=name,
            matched=score >= TEMPLATE_PAGE,
            score=score,
            threshold=TEMPLATE_PAGE,
        )

    # ── 状态查询 — 舰队 / 面板 ────────────────────────────────────────────

    @staticmethod
    def get_selected_fleet(screen: np.ndarray) -> int | None:
        """获取当前选中的舰队编号 (1-4)。"""
        for fleet_id, (x, y) in FLEET_PROBE.items():
            pixel = PixelChecker.get_pixel(screen, x, y)
            if pixel.near(FLEET_ACTIVE, STATE_TOLERANCE):
                return fleet_id
        return None

    @staticmethod
    def get_active_panel(screen: np.ndarray) -> Panel | None:
        """获取当前激活的底部面板。"""
        for panel, (x, y) in PANEL_PROBE.items():
            pixel = PixelChecker.get_pixel(screen, x, y)
            if pixel.near(PANEL_ACTIVE, STATE_TOLERANCE):
                return panel
        return None

    @staticmethod
    def is_auto_supply_enabled(screen: np.ndarray) -> bool:
        """检测自动补给是否启用。"""
        x, y = AUTO_SUPPLY_PROBE
        return PixelChecker.get_pixel(screen, x, y).near(AUTO_SUPPLY_ON, STATE_TOLERANCE)

    # ── 动作 — 回退 / 出征 ───────────────────────────────────────────────

    def go_back(self) -> None:
        """点击回退按钮 (◁)，返回地图页面。

        用**到达验证** (:func:`click_and_wait_for_page`): 点击后确认真的到了
        地图页面。此前用 ``wait_leave_page`` 语义 (checker 为 False 即"已离开")
        存在假成功——点击后画面仍在出征准备页时, ``MapPage.is_current_page``
        同样为 False, 第一帧就误判离开, 从未验证到达。
        """
        from autowsgr.ui.map.page import MapPage

        _log.debug('[UI] 出征准备 → 回退')
        click_and_wait_for_page(
            self._ctrl,
            click_coord=CLICK_BACK,
            checker=MapPage.is_current_page,
            source=PageName.BATTLE_PREP,
            target=PageName.MAP,
            stop_event=self._ctx.stop_event,
        )

    def start_battle(self) -> None:
        """点击「开始出征」按钮。"""
        _log.info('[UI] 出征准备 → 开始出征')
        self._ctrl.click(*CLICK_START_BATTLE)

    # ── 动作 — 舰队 / 面板选择 ───────────────────────────────────────────

    _SELECT_CONFIG = NavConfig(
        max_retries=2,
        retry_delay=0.4,
        timeout=2.0,
        interval=0.25,
        stable_frames=2,
    )
    """舰队 / 面板选择的闭环配置：点击后连续两帧命中目标选中态。"""

    def select_fleet(self, fleet: int) -> None:
        """选择舰队 (1-4)，并验证切换**确实生效**。

        旧实现点完就走：点击若被入场动画吞掉，后续补给 / 修理 / 换船全部
        作用在错误的舰队上，而日志里看不出任何异常。现在以
        :meth:`get_selected_fleet` 的像素探针为准，由
        :class:`~autowsgr.ui.substate.SubstateSpec` 完成「点击 → 连续两帧
        验证 → 必要时重试」。

        探测点失效（主题或分辨率变化导致 ``None``）时**不重复点击**，
        只记一条 warning 并按旧行为返回——无法验证不等于必然失败，
        不该把它升级成错误。
        """
        if fleet not in CLICK_FLEET:
            raise ValueError(f'舰队编号必须为 1-4，收到: {fleet}')

        current = self.get_selected_fleet(self._ctrl.screenshot())
        if current == fleet:
            _log.debug('[UI] 出征准备 → {}队 已是目标舰队, 跳过点击', fleet)
            record_page_substate(self._ctx, PageName.BATTLE_PREP, f'{fleet}队')
            return
        if current is not None:
            _log.debug('[UI] 出征准备 → 选择 {}队 (当前 {}队)', fleet, current)

        SubstateSpec(
            page=PageName.BATTLE_PREP.value,
            substate=f'{fleet}队',
            checker=lambda screen: self.get_selected_fleet(screen) == fleet,
            timeout=self._SELECT_CONFIG.timeout,
            retries=self._SELECT_CONFIG.max_retries,
            interval=self._SELECT_CONFIG.interval,
            stable_frames=self._SELECT_CONFIG.stable_frames,
            probe=lambda screen: self.get_selected_fleet(screen) is not None,
        ).click(
            self._ctx,
            CLICK_FLEET[fleet],
            source='出征准备-舰队',
            action_name='select_fleet',
        )

    def select_panel(self, panel: Panel) -> None:
        """切换底部面板标签，并验证**确实切过去了**。

        与 :meth:`select_fleet` 同一套策略：探针可用时闭环验证并重试，
        探针失效时由 ``SubstateSpec`` 降级为「点一次、不验证」。
        """
        current = self.get_active_panel(self._ctrl.screenshot())
        if current == panel:
            _log.debug('[UI] 出征准备 → {} 已是目标面板, 跳过点击', panel.value)
            record_page_substate(self._ctx, PageName.BATTLE_PREP, panel.value)
            return
        if current is not None:
            _log.debug('[UI] 出征准备 → {} (当前 {})', panel.value, current.value)

        SubstateSpec(
            page=PageName.BATTLE_PREP.value,
            substate=panel.value,
            checker=lambda screen: self.get_active_panel(screen) == panel,
            timeout=self._SELECT_CONFIG.timeout,
            retries=self._SELECT_CONFIG.max_retries,
            interval=self._SELECT_CONFIG.interval,
            stable_frames=self._SELECT_CONFIG.stable_frames,
            probe=lambda screen: self.get_active_panel(screen) is not None,
        ).click(
            self._ctx,
            CLICK_PANEL[panel],
            source='出征准备-面板',
            action_name='select_panel',
        )

    def quick_supply(self) -> None:
        """点击「快速补给」标签。"""
        self.select_panel(Panel.QUICK_SUPPLY)

    def quick_repair(self) -> None:
        """点击「快速修理」标签。"""
        self.select_panel(Panel.QUICK_REPAIR)

    # ── 动作 — 舰船槽位 ─────────────────────────────────────────────────

    def click_ship_slot(self, slot: int) -> None:
        """点击指定舰船槽位 (0-5)，并验证进入选船页面。"""
        if slot not in CLICK_SHIP_SLOT:
            raise ValueError(f'舰船槽位必须为 0-5，收到: {slot}')
        from autowsgr.ui.choose_ship_page import ChooseShipPage

        _log.debug('[UI] 出征准备 → 点击舰船位 {}', slot)
        click_and_wait_for_page(
            self._ctrl,
            click_coord=CLICK_SHIP_SLOT[slot],
            checker=ChooseShipPage.is_current_page,
            source=PageName.BATTLE_PREP,
            target=PageName.CHOOSE_SHIP,
            stop_event=self._ctx.stop_event,
        )

    # ── 动作 — 开关 ──────────────────────────────────────────────────────

    def toggle_auto_supply(self) -> None:
        """切换自动补给开关，并验证开关状态确实翻转。

        开关探针失效时只点一次并 warning——无法验证不等于必然失败。
        """
        _log.debug('[UI] 出征准备 → 切换自动补给')
        desired = not self.is_auto_supply_enabled(self._ctrl.screenshot())
        try:
            click_and_wait_for_page(
                self._ctrl,
                click_coord=CLICK_AUTO_SUPPLY,
                checker=lambda screen: self.is_auto_supply_enabled(screen) == desired,
                source='出征准备-自动补给',
                target='自动补给/开' if desired else '自动补给/关',
                config=NavConfig(
                    max_retries=1,
                    retry_delay=0.0,
                    timeout=1.5,
                    interval=0.25,
                    stable_frames=2,
                ),
                stop_event=self._ctx.stop_event,
            )
        except NavigationError:
            _log.warning('[UI] 出征准备: 自动补给开关状态未确认 (已点击一次)')
